//! Users and Subsonic authentication.
//!
//! Subsonic's token scheme (`t = md5(password + salt)`, `s = salt`) means the server must know
//! the password itself, so passwords are stored in clear in the users file (mode 0600, in the
//! config directory). They are random and generated by `codjd user add`, one per device, so a
//! leaked file exposes only codjd credentials nobody reuses. The alternative, hashing, would
//! break token auth, which most apps use.
//!
//! Each user also has an `api_key` for OpenSubsonic's `apiKey` extension (sent alone, no
//! username or password).

use std::{
    path::{Path, PathBuf},
    sync::Mutex,
    time::SystemTime,
};

use rand::Rng;
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Clone, PartialEq, Eq)]
pub struct User {
    pub name: String,
    pub password: String,
    pub api_key: String,
    /// unix seconds
    pub created: u64,
}

// no secrets in logs or panics
impl std::fmt::Debug for User {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("User").field("name", &self.name).finish_non_exhaustive()
    }
}

#[derive(Serialize, Deserialize, Default)]
struct UsersFile {
    #[serde(default)]
    user: Vec<User>,
}

/// What a request presented
#[derive(Debug, Default, Clone)]
pub struct Credentials {
    pub u: Option<String>,
    pub p: Option<String>,
    pub t: Option<String>,
    pub s: Option<String>,
    pub api_key: Option<String>,
}

/// A Subsonic error: code and message
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AuthError {
    pub code: u32,
    pub message: &'static str,
}

const MISSING: AuthError = AuthError { code: 10, message: "Required parameter is missing" };
const WRONG: AuthError = AuthError { code: 40, message: "Wrong username or password" };
const CONFLICT: AuthError = AuthError {
    code: 43,
    message: "Multiple conflicting authentication mechanisms provided",
};
const BAD_KEY: AuthError = AuthError { code: 44, message: "Invalid API key" };

/// Equal without stopping at the first difference
pub fn ct_eq(a: &[u8], b: &[u8]) -> bool {
    let mut diff = (a.len() != b.len()) as u8;
    for i in 0..a.len().max(b.len()) {
        diff |= a.get(i).copied().unwrap_or(0) ^ b.get(i).copied().unwrap_or(0);
    }
    diff == 0
}

pub fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

pub fn unhex(s: &str) -> Option<Vec<u8>> {
    if s.len() % 2 != 0 || !s.is_ascii() {
        return None;
    }
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).ok())
        .collect()
}

/// The plain password out of a `p` parameter (`enc:` + hex, or as is)
fn decode_p(p: &str) -> Vec<u8> {
    match p.strip_prefix("enc:").and_then(unhex) {
        Some(bytes) => bytes,
        None => p.as_bytes().to_vec(),
    }
}

/// Checks the credentials against `users`. Compares every user and every secret in constant time
/// so response time doesn't tell which names exist.
pub fn authenticate(users: &[User], c: &Credentials) -> Result<User, AuthError> {
    let password_auth = c.u.is_some() || c.p.is_some() || c.t.is_some() || c.s.is_some();
    if let Some(key) = &c.api_key {
        if password_auth {
            return Err(CONFLICT);
        }
        let mut found = None;
        for user in users {
            if ct_eq(user.api_key.as_bytes(), key.as_bytes()) {
                found = Some(user);
            }
        }
        return found.cloned().ok_or(BAD_KEY);
    }
    let Some(name) = &c.u else {
        return Err(MISSING);
    };
    if c.p.is_some() == c.t.is_some() {
        // both, or neither
        return Err(if c.p.is_some() { CONFLICT } else { MISSING });
    }
    let mut found = None;
    for user in users {
        let ok_name = ct_eq(user.name.as_bytes(), name.as_bytes());
        let ok_secret = if let Some(p) = &c.p {
            ct_eq(&decode_p(p), user.password.as_bytes())
        } else {
            let salt = c.s.as_deref().unwrap_or("");
            let expected = format!("{:x}", md5::compute(format!("{}{salt}", user.password)));
            ct_eq(expected.as_bytes(), c.t.as_deref().unwrap_or("").to_ascii_lowercase().as_bytes())
        };
        if ok_name & ok_secret {
            found = Some(user);
        }
    }
    if c.t.is_some() && c.s.is_none() {
        return Err(MISSING);
    }
    found.cloned().ok_or(WRONG)
}

/// The users file, re-read when it changes so `codjd user add` works on a running daemon
pub struct Users {
    path: PathBuf,
    cache: Mutex<(Option<(SystemTime, u64)>, Vec<User>)>,
}

impl Users {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into(), cache: Mutex::new((None, vec![])) }
    }

    /// `CODJD_USERS_FILE`, or `users.toml` in codjd's config directory
    pub fn default_path() -> PathBuf {
        std::env::var_os("CODJD_USERS_FILE")
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                dirs::config_dir().unwrap_or_else(|| PathBuf::from(".")).join("codjd/users.toml")
            })
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    fn read(&self) -> Vec<User> {
        std::fs::read_to_string(&self.path)
            .ok()
            .and_then(|s| toml::from_str::<UsersFile>(&s).ok())
            .unwrap_or_default()
            .user
    }

    pub fn list(&self) -> Vec<User> {
        let stamp = std::fs::metadata(&self.path)
            .ok()
            .and_then(|m| Some((m.modified().ok()?, m.len())));
        let mut cache = self.cache.lock().unwrap_or_else(|e| e.into_inner());
        if cache.0 != stamp || stamp.is_none() {
            *cache = (stamp, self.read());
        }
        cache.1.clone()
    }

    pub fn authenticate(&self, c: &Credentials) -> Result<User, AuthError> {
        authenticate(&self.list(), c)
    }

    fn write(&self, users: Vec<User>) -> std::io::Result<()> {
        use std::io::Write;
        use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
        if let Some(dir) = self.path.parent().filter(|d| !d.as_os_str().is_empty()) {
            std::fs::DirBuilder::new().recursive(true).mode(0o700).create(dir)?;
        }
        let text = toml::to_string_pretty(&UsersFile { user: users }).map_err(std::io::Error::other)?;
        let tmp = self.path.with_extension("tmp");
        let mut f = std::fs::OpenOptions::new()
            .write(true)
            .create(true)
            .truncate(true)
            .mode(0o600)
            .open(&tmp)?;
        f.write_all(text.as_bytes())?;
        f.sync_all()?;
        std::fs::rename(tmp, &self.path)
    }

    /// Creates a user with a fresh random password and API key (returned once, in the clear)
    pub fn add(&self, name: &str) -> std::io::Result<User> {
        if !valid_name(name) {
            return Err(std::io::Error::other(
                "names are 1-32 characters of letters, digits, '.', '_' and '-'",
            ));
        }
        let mut users = self.read();
        if users.iter().any(|u| u.name == name) {
            return Err(std::io::Error::other(format!("user '{name}' exists (use `user reset`)")));
        }
        let user = new_user(name);
        users.push(user.clone());
        self.write(users)?;
        Ok(user)
    }

    /// New password and API key for an existing user
    pub fn reset(&self, name: &str) -> std::io::Result<User> {
        let mut users = self.read();
        let Some(slot) = users.iter_mut().find(|u| u.name == name) else {
            return Err(std::io::Error::other(format!("no user '{name}'")));
        };
        let fresh = new_user(name);
        slot.password = fresh.password;
        slot.api_key = fresh.api_key;
        let user = slot.clone();
        self.write(users)?;
        Ok(user)
    }

    pub fn remove(&self, name: &str) -> std::io::Result<()> {
        let mut users = self.read();
        let before = users.len();
        users.retain(|u| u.name != name);
        if users.len() == before {
            return Err(std::io::Error::other(format!("no user '{name}'")));
        }
        self.write(users)
    }
}

fn valid_name(name: &str) -> bool {
    (1..=32).contains(&name.len())
        && name.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-'))
}

fn new_user(name: &str) -> User {
    // no look-alike characters, so a password typed in from a screen works
    const ALPHABET: &[u8] = b"abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    let mut rng = rand::rng();
    let password: String =
        (0..20).map(|_| ALPHABET[rng.random_range(0..ALPHABET.len())] as char).collect();
    let key: Vec<u8> = (0..16).map(|_| rng.random::<u8>()).collect();
    User {
        name: name.to_string(),
        password,
        api_key: hex(&key),
        created: SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0),
    }
}

/// `codjd user add|reset|remove|list ...`; returns the exit code
pub fn cli(args: &[String]) -> i32 {
    let users = Users::new(Users::default_path());
    let show = |user: &User| {
        println!("user      {}", user.name);
        println!("password  {}", user.password);
        println!("api key   {}", user.api_key);
        println!("(shown once here; stored in {})", users.path().display());
    };
    let result = match args.first().map(String::as_str) {
        Some("add") if args.len() == 2 => users.add(&args[1]).map(|u| show(&u)),
        Some("reset") if args.len() == 2 => users.reset(&args[1]).map(|u| show(&u)),
        Some("remove") if args.len() == 2 => users.remove(&args[1]),
        Some("list") if args.len() == 1 => {
            for u in users.list() {
                println!("{}", u.name);
            }
            Ok(())
        }
        _ => {
            eprintln!("usage: codjd user add <name> | reset <name> | remove <name> | list");
            return 2;
        }
    };
    match result {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("{e}");
            1
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn alice() -> User {
        User { name: "alice".into(), password: "s3cret".into(), api_key: "abc123".into(), created: 0 }
    }

    fn creds(f: impl FnOnce(&mut Credentials)) -> Credentials {
        let mut c = Credentials::default();
        f(&mut c);
        c
    }

    #[test]
    fn token_and_salt() {
        let users = [alice()];
        let t = format!("{:x}", md5::compute("s3cretsalt1"));
        let ok = creds(|c| {
            c.u = Some("alice".into());
            c.t = Some(t.clone());
            c.s = Some("salt1".into());
        });
        assert_eq!(authenticate(&users, &ok).unwrap().name, "alice");
        // upper-case hex is accepted
        let upper = creds(|c| {
            c.u = Some("alice".into());
            c.t = Some(t.to_uppercase());
            c.s = Some("salt1".into());
        });
        assert!(authenticate(&users, &upper).is_ok());
        // wrong salt, missing salt
        let bad = creds(|c| {
            c.u = Some("alice".into());
            c.t = Some(t.clone());
            c.s = Some("other".into());
        });
        assert_eq!(authenticate(&users, &bad).unwrap_err().code, 40);
        let nosalt = creds(|c| {
            c.u = Some("alice".into());
            c.t = Some(t);
        });
        assert_eq!(authenticate(&users, &nosalt).unwrap_err().code, 10);
    }

    #[test]
    fn plain_and_enc_password() {
        let users = [alice()];
        let plain = creds(|c| {
            c.u = Some("alice".into());
            c.p = Some("s3cret".into());
        });
        assert!(authenticate(&users, &plain).is_ok());
        assert_eq!(hex(b"s3cret"), "733363726574");
        let c = creds(|c| {
            c.u = Some("alice".into());
            c.p = Some("enc:733363726574".into());
        });
        assert!(authenticate(&users, &c).is_ok());
        let wrong = creds(|c| {
            c.u = Some("alice".into());
            c.p = Some("enc:733363726575".into());
        });
        assert_eq!(authenticate(&users, &wrong).unwrap_err().code, 40);
        let unknown = creds(|c| {
            c.u = Some("bob".into());
            c.p = Some("s3cret".into());
        });
        assert_eq!(authenticate(&users, &unknown).unwrap_err().code, 40);
    }

    #[test]
    fn missing_and_conflicting() {
        let users = [alice()];
        assert_eq!(authenticate(&users, &Credentials::default()).unwrap_err().code, 10);
        let no_secret = creds(|c| c.u = Some("alice".into()));
        assert_eq!(authenticate(&users, &no_secret).unwrap_err().code, 10);
        let both = creds(|c| {
            c.u = Some("alice".into());
            c.p = Some("s3cret".into());
            c.t = Some("x".into());
            c.s = Some("y".into());
        });
        assert_eq!(authenticate(&users, &both).unwrap_err().code, 43);
        let mixed = creds(|c| {
            c.u = Some("alice".into());
            c.api_key = Some("abc123".into());
        });
        assert_eq!(authenticate(&users, &mixed).unwrap_err().code, 43);
    }

    #[test]
    fn api_key() {
        let users = [alice()];
        let ok = creds(|c| c.api_key = Some("abc123".into()));
        assert_eq!(authenticate(&users, &ok).unwrap().name, "alice");
        let bad = creds(|c| c.api_key = Some("nope".into()));
        assert_eq!(authenticate(&users, &bad).unwrap_err().code, 44);
        assert_eq!(authenticate(&[], &ok).unwrap_err().code, 44);
    }

    #[test]
    fn constant_time_compare() {
        assert!(ct_eq(b"abc", b"abc"));
        assert!(!ct_eq(b"abc", b"abd"));
        assert!(!ct_eq(b"abc", b"abcd"));
        assert!(!ct_eq(b"", b"a"));
        assert!(ct_eq(b"", b""));
    }

    #[test]
    fn file_roundtrip_and_permissions() {
        use std::os::unix::fs::PermissionsExt;
        let dir = std::env::temp_dir().join(format!("codj-users-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let users = Users::new(dir.join("sub/users.toml"));
        let a = users.add("phone").unwrap();
        assert_eq!(a.password.len(), 20);
        assert_eq!(a.api_key.len(), 32);
        assert!(users.add("phone").is_err());
        assert!(users.add("bad name!").is_err());
        let mode = std::fs::metadata(users.path()).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o600);
        let c = creds(|c| {
            c.u = Some("phone".into());
            c.p = Some(a.password.clone());
        });
        assert!(users.authenticate(&c).is_ok());
        let b = users.reset("phone").unwrap();
        assert_ne!(a.password, b.password);
        assert!(users.authenticate(&c).is_err());
        users.remove("phone").unwrap();
        assert!(users.list().is_empty());
        assert!(users.remove("phone").is_err());
        let _ = std::fs::remove_dir_all(dir);
    }
}
